#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long left, right;
    cin >> left >> right;

    vector<long long> lucky = {4, 7};

    for (size_t i = 0; i < lucky.size() && lucky[i] <= right; ++i) {
        lucky.push_back(lucky[i] * 10 + 4);
        lucky.push_back(lucky[i] * 10 + 7);
    }

    sort(lucky.begin(), lucky.end());

    long long answer = 0;
    long long current = left;

    for (long long value : lucky) {
        if (value < current)
            continue;

        long long end = min(right, value);
        answer += (end - current + 1) * value;
        current = end + 1;

        if (current > right)
            break;
    }

    cout << answer;
    return 0;
}

